/**
 * Users Routes — Worker lookup for repair assignment and staff management.
 */

import { Hono } from 'hono'
import {
  getActiveWorkers,
  listUsersPaginated,
  createUser,
  updateUser,
  StaffNotFoundError,
  type StaffListQuery,
} from '../services/users.service.js'
import { createStaffMemberSchema, updateStaffMemberSchema } from '@shared/validations/staff.js'

const usersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /users — Dual-mode endpoint
//
// When called without query parameters, returns a compact shape:
// id, name, role. Only active workers (isActive=true).
// Suitable for populating repair assignment dropdowns.
//
// When called with ?search= and/or ?page= parameters, returns full staff member
// details with pagination — suitable for the management list view.
// ---------------------------------------------------------------------------

usersRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const page = c.req.query('page')
  const pageSize = c.req.query('pageSize')

  // If pagination or search params are present, return paginated full details
  if (search !== undefined || page !== undefined || pageSize !== undefined) {
    const query: StaffListQuery = {}
    if (search !== undefined && search !== '') query.search = search
    if (page !== undefined) query.page = parseInt(page, 10)
    if (pageSize !== undefined) query.pageSize = parseInt(pageSize, 10)

    return c.json(await listUsersPaginated(query))
  }

  // Default: compact selector shape for POS dropdown consumers
  const workers = await getActiveWorkers()
  return new Response(JSON.stringify(workers), {
    headers: { 'Content-Type': 'application/json' },
  })
})

// ---------------------------------------------------------------------------
// POST /users — Create a new staff member
// ---------------------------------------------------------------------------

usersRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const validated = createStaffMemberSchema.parse(input)
    const user = await createUser(validated)
    return c.json(user, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }
    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// PATCH /users/:id — Update a staff member (partial update)
// ---------------------------------------------------------------------------

usersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const input = await c.req.json()
    const validated = updateStaffMemberSchema.parse(input)
    const user = await updateUser(id, validated)
    return c.json(user)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    if (err instanceof StaffNotFoundError) {
      return c.json({ error: 'Staff member not found', code: 'NOT_FOUND' }, 404)
    }

    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

export default usersRoutes

/**
 * Users Service — Worker lookup for repair assignment and staff management.
 */

import crypto from 'crypto'
import { asc, eq, sql } from 'drizzle-orm'
import { db } from '../db/index.js'
import { users, type User as DbUser } from '../db/schema.js'
import {
  createStaffMemberSchema,
  updateStaffMemberSchema,
  type CreateStaffMemberInput,
  type UpdateStaffMemberInput,
} from '@shared/validations/staff.js'

// ---------------------------------------------------------------------------
// Types — compact dropdown shape (existing)
// ---------------------------------------------------------------------------

/** Compact worker shape for dropdown selectors (name + role only) */
export interface WorkerOption {
  id: string
  name: string
  role: 'mechanic' | 'manager'
}

// ---------------------------------------------------------------------------
// Types — paginated management list
// ---------------------------------------------------------------------------

/** Full staff member detail for the management list. */
export interface StaffMemberDetail {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date
}

/** Query parameters for the paginated staff list. */
export interface StaffListQuery {
  /** Search term — filters by name */
  search?: string
  /** Page number (1-indexed) */
  page?: number
  /** Items per page */
  pageSize?: number
}

/** Paginated response for the staff management list. */
export interface StaffPaginatedResponse {
  users: StaffMemberDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Functions — compact dropdown (existing)
// ---------------------------------------------------------------------------

/**
 * List all active workers, suitable for populating a worker assignment dropdown.
 * Returns workers sorted by name for consistent display order.
 */
export async function getActiveWorkers(): Promise<WorkerOption[]> {
  const rows = await db
    .select({
      id: users.id,
      name: users.name,
      role: users.role,
    })
    .from(users)
    .where(eq(users.isActive, true))
    .orderBy(users.name)

  return rows as unknown as WorkerOption[]
}

// ---------------------------------------------------------------------------
// Functions — create staff member
// ---------------------------------------------------------------------------

/**
 * Create a new staff member.
 *
 * Generates a UUID if not provided, applies defaults (role=mechanic, isActive=true),
 * and inserts into the users table. Returns the created StaffMemberDetail.
 */
export async function createUser(input: CreateStaffMemberInput): Promise<StaffMemberDetail> {
  const validated = createStaffMemberSchema.parse(input)

  const dbData = {
    id: validated.id ?? crypto.randomUUID(),
    name: validated.name,
    role: validated.role as 'mechanic' | 'manager',
    hourlyRate: validated.hourlyRate,
    isActive: validated.isActive ?? true,
  }

  const [created] = await db.insert(users).values(dbData).returning()
  return toStaffMemberDetail(created)
}

// ---------------------------------------------------------------------------
// Functions — paginated management list
// ---------------------------------------------------------------------------

/**
 * Get paginated staff member list with optional search filtering.
 *
 * Returns full StaffMemberDetail records suitable for the management view.
 * Search filters by name using SQL LIKE. Includes both active and inactive members.
 *
 * @param query - Optional search term, page number, and page size
 * @returns Paginated response with staff members and pagination metadata
 */
export async function listUsersPaginated(
  query: StaffListQuery = {}
): Promise<StaffPaginatedResponse> {
  const { search, page = 1, pageSize = 25 } = query
  const offset = (page - 1) * pageSize

  // Build filter conditions for search
  let whereClause: ReturnType<typeof sql> | undefined

  if (search && search.trim()) {
    const term = `%${search.trim()}%`
    whereClause = sql`LOWER(${users.name}) LIKE ${term.toLowerCase()}`
  }

  // Get total count for pagination
  let totalCount = 0
  if (whereClause) {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users).where(whereClause)
    totalCount = count
  } else {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users)
    totalCount = count
  }

  // Get paginated results
  let results: DbUser[]
  if (whereClause) {
    results = await db.select().from(users).where(whereClause)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  } else {
    results = await db.select().from(users)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  }

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))

  return {
    users: results.map(toStaffMemberDetail),
    totalItems: totalCount,
    currentPage: page,
    pageSize,
    totalPages,
  }
}

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

export class StaffNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Staff member not found: ${id}`)
    this.name = 'StaffNotFoundError'
  }
}

// ---------------------------------------------------------------------------
// Functions — get by ID
// ---------------------------------------------------------------------------

/**
 * Get a single staff member by ID.
 *
 * @throws StaffNotFoundError if user doesn't exist
 */
export async function getUserById(id: string): Promise<StaffMemberDetail> {
  const [user] = await db.select().from(users).where(eq(users.id, id))

  if (!user) {
    throw new StaffNotFoundError(id)
  }

  return toStaffMemberDetail(user)
}

// ---------------------------------------------------------------------------
// Functions — update staff member (partial)
// ---------------------------------------------------------------------------

/**
 * Update an existing staff member with partial fields.
 *
 * Only provided fields are changed. Validates against Zod schema which requires
 * at least one field to be present.
 *
 * @throws StaffNotFoundError if user doesn't exist
 * @throws ZodError if validation fails (empty payload, invalid role, etc.)
 */
export async function updateUser(
  id: string,
  input: UpdateStaffMemberInput,
): Promise<StaffMemberDetail> {
  // Validate — ensures at least one field is provided and values are valid
  const validated = updateStaffMemberSchema.parse(input)

  // Build partial DB update object (only include defined fields)
  const dbUpdate: Record<string, unknown> = {}
  if (validated.name !== undefined) dbUpdate.name = validated.name
  if (validated.role !== undefined) dbUpdate.role = validated.role as 'mechanic' | 'manager'
  if (validated.hourlyRate !== undefined) dbUpdate.hourlyRate = validated.hourlyRate
  if (validated.isActive !== undefined) dbUpdate.isActive = validated.isActive

  const [updated] = await db
    .update(users)
    .set(dbUpdate)
    .where(eq(users.id, id))
    .returning()

  if (!updated) {
    throw new StaffNotFoundError(id)
  }

  return toStaffMemberDetail(updated)
}

// ---------------------------------------------------------------------------
// Helpers — map between DB User and DTO shapes
// ---------------------------------------------------------------------------

/** Map a DB User to the full staff member detail shape. */
function toStaffMemberDetail(user: DbUser): StaffMemberDetail {
  return {
    id: user.id,
    name: user.name,
    role: user.role as 'mechanic' | 'manager',
    hourlyRate: user.hourlyRate,
    isActive: user.isActive,
    createdAt: user.createdAt,
  }
}

import { z } from 'zod'

// ---------------------------------------------------------------------------
// Role enum
// ---------------------------------------------------------------------------

export const staffRoleSchema = z.enum(['mechanic', 'manager'])

/** A staff member role */
export type StaffRole = z.infer<typeof staffRoleSchema>

// ---------------------------------------------------------------------------
// Create input schema
// ---------------------------------------------------------------------------

/** Input for creating a new staff member. */
export const createStaffMemberSchema = z.object({
  id: z.string().uuid('id must be a valid UUID').optional(),
  name: z.string().min(1, 'name is required').max(200),
  role: staffRoleSchema.default('mechanic'),
  hourlyRate: z.number()
    .int('hourlyRate must be an integer (cents)')
    .positive('hourlyRate must be positive'),
  isActive: z.boolean().optional(),
})

/** Input for creating a new staff member. */
export type CreateStaffMemberInput = z.infer<typeof createStaffMemberSchema>

// ---------------------------------------------------------------------------
// Update input schema — partial fields, at least one required
// ---------------------------------------------------------------------------

const updatableFields = [
  'name', 'role', 'hourlyRate', 'isActive'
] as const

/** Input for updating an existing staff member (partial). */
export const updateStaffMemberSchema = z.object({
  name: z.string().min(1, 'name must not be empty').max(200).optional(),
  role: staffRoleSchema.optional(),
  hourlyRate: z.number()
    .int('hourlyRate must be an integer (cents)')
    .positive('hourlyRate must be positive')
    .optional(),
  isActive: z.boolean().optional(),
}).refine(
  data => updatableFields.some(key => data[key] !== undefined),
  { message: 'At least one field must be provided for update' }
)

/** Input for updating an existing staff member. */
export type UpdateStaffMemberInput = z.infer<typeof updateStaffMemberSchema>

/**
 * Explicit TypeScript interfaces for staff members (users).
 * Mirrors the DB schema's `users` table but is decoupled from Drizzle inference.
 */

export interface StaffMember {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date
}

/** Input for creating a new staff member. */
export interface NewStaffMember {
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive?: boolean
}

/** Input for updating an existing staff member (partial). */
export interface UpdateStaffMember {
  name?: string
  role?: 'mechanic' | 'manager'
  hourlyRate?: number // cents per hour
  isActive?: boolean
}

/**
 * StaffFormDialog — Radix Dialog modal for creating or editing a staff member.
 *
 * Fields: name (text), role (select: mechanic/manager), hourly rate (number input in cents/hour, displayed as €X.XX/h)
 * Supports both create mode (empty form) and edit mode (pre-populated with existing values).
 */

import { useCallback, useEffect, useState } from 'react'
import * as DialogPrimitive from '@radix-ui/react-dialog'
import { X } from 'lucide-react'
import { cn } from '@/shared/lib/utils.js'
import { Button } from '@/components/ui/button.js'
import { Input } from '@/components/ui/input.js'
import { Label } from '@/components/ui/label.js'
import { createStaffMember, updateStaffMember } from '../api.js'

// ---------------------------------------------------------------------------
// Form State Shape
// ---------------------------------------------------------------------------

interface StaffFormData {
  name: string
  role: 'mechanic' | 'manager'
  hourlyRateCents: number // stored as cents/hour in DB
}

/** Default empty form state */
const createEmptyForm = (): StaffFormData => ({
  name: '',
  role: 'mechanic',
  hourlyRateCents: 0,
})

// ---------------------------------------------------------------------------
// Validation Helpers (mirrors shared Zod schemas)
// ---------------------------------------------------------------------------

interface FormErrors {
  fields: Record<string, string>
  general?: string
}

/** Validate the form data against business rules. Returns null if valid. */
function validateForm(data: StaffFormData): FormErrors | null {
  const fields: Record<string, string> = {}

  if (!data.name.trim()) {
    fields.name = 'Name is required'
  } else if (data.name.length > 200) {
    fields.name = 'Name must be at most 200 characters'
  }

  if (data.hourlyRateCents <= 0) {
    fields.hourlyRateCents = 'Hourly rate must be positive'
  } else if (!Number.isInteger(data.hourlyRateCents)) {
    fields.hourlyRateCents = 'Must be a whole number (cents/hour)'
  }

  return Object.keys(fields).length > 0 ? { fields } : null
}

/** Helper to create an empty errors object */
const emptyErrors: FormErrors = { fields: {} }

// ---------------------------------------------------------------------------
// Main Dialog Component
// ---------------------------------------------------------------------------

interface StaffFormDialogProps {
  /** Whether the dialog is open */
  open: boolean
  /** Callback when dialog opens/closes */
  onOpenChange: (open: boolean) => void
  /** Called after successful save — typically to refresh the list */
  onSaveSuccess: () => void
  /** Pre-populated data for edit mode. If provided, form is in edit mode. */
  initialData?: { id: string; name: string; role: 'mechanic' | 'manager'; hourlyRateCents: number }
}

export function StaffFormDialog({
  open,
  onOpenChange,
  onSaveSuccess,
  initialData,
}: StaffFormDialogProps) {
  const [formData, setFormData] = useState<StaffFormData>(createEmptyForm)
  const [errors, setErrors] = useState<FormErrors | null>(null)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Determine if in edit mode
  const isEditMode = !!initialData

  // Populate form when dialog opens
  useEffect(() => {
    if (open) {
      if (initialData) {
        setFormData({
          name: initialData.name,
          role: initialData.role,
          hourlyRateCents: initialData.hourlyRateCents,
        })
      } else {
        setFormData(createEmptyForm())
      }
      setErrors(null)
      setIsSubmitting(false)
    }
  }, [open, initialData])

  // -----------------------------------------------------------------------
  // Field change handler
  // -----------------------------------------------------------------------

  const handleFieldChange = useCallback((name: string, value: string) => {
    if (name === 'hourlyRateCents') {
      setFormData((prev) => ({ ...prev, [name]: parseInt(value, 10) || 0 }))
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }))
    }
    // Clear field error when user starts typing
    if (errors && errors.fields[name]) {
      setErrors({ ...errors, fields: { ...errors.fields, [name]: '' } })
    }
  }, [errors])

  // -----------------------------------------------------------------------
  // Submit handler
  // -----------------------------------------------------------------------

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault()

    // Validate before submission
    const validationErrors = validateForm(formData)
    if (validationErrors) {
      setErrors(validationErrors)
      return
    }

    setIsSubmitting(true)
    setErrors(emptyErrors)

    try {
      const payload = {
        name: formData.name.trim(),
        role: formData.role,
        hourlyRate: formData.hourlyRateCents,
      }

      if (isEditMode && initialData) {
        await updateStaffMember(initialData.id, payload)
      } else {
        await createStaffMember(payload)
      }

      onSaveSuccess()
      onOpenChange(false)
    } catch (err) {
      const message = err instanceof Error ? err.message : `Failed to ${isEditMode ? 'update' : 'create'} staff member`
      setErrors({ fields: {}, general: message })
    } finally {
      setIsSubmitting(false)
    }
  }, [formData, onSaveSuccess, onOpenChange, isEditMode, initialData])

  // -----------------------------------------------------------------------
  // Dialog close handler — resets state
  // -----------------------------------------------------------------------

  const handleClose = useCallback(() => {
    setFormData(createEmptyForm())
    setErrors(null)
    setIsSubmitting(false)
    onOpenChange(false)
  }, [onOpenChange])

  // -----------------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------------

  return (
    <DialogPrimitive.Root open={open} onOpenChange={handleClose}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <DialogPrimitive.Content
          className={cn(
            'fixed left-[50%] top-[50%] z-50 w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg',
            'max-h-[90vh] overflow-y-auto'
          )}
        >
          {/* Header */}
          <div className="flex items-center justify-between">
            <DialogPrimitive.Title className="text-lg font-semibold leading-none tracking-tight">
              {isEditMode ? 'Edit Staff Member' : 'New Staff Member'}
            </DialogPrimitive.Title>
            <DialogPrimitive.Close asChild>
              <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                <X className="h-4 w-4" />
                <span className="sr-only">Close</span>
              </Button>
            </DialogPrimitive.Close>
          </div>

          {/* General error */}
          {errors?.general && (
            <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
              {errors.general}
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Name field */}
            <div className="space-y-1.5">
              <Label htmlFor="name" className={cn(errors?.fields.name && 'text-destructive')}>
                Name
              </Label>
              <Input
                id="name"
                name="name"
                type="text"
                value={formData.name}
                onChange={(e) => handleFieldChange('name', e.target.value)}
                placeholder="e.g. Jan Kowalski"
                className={cn(errors?.fields.name && 'border-destructive focus-visible:ring-destructive')}
              />
              {errors?.fields.name && (
                <p className="text-xs text-destructive">{errors.fields.name}</p>
              )}
            </div>

            {/* Role selector */}
            <div className="space-y-1.5">
              <Label htmlFor="role">Role</Label>
              <select
                id="role"
                value={formData.role}
                onChange={(e) => handleFieldChange('role', e.target.value)}
                className={cn(
                  'flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50'
                )}
              >
                <option value="mechanic">Mechanic</option>
                <option value="manager">Manager</option>
              </select>
            </div>

            {/* Hourly rate field */}
            <div className="space-y-1.5">
              <Label htmlFor="hourlyRateCents" className={cn(errors?.fields.hourlyRateCents && 'text-destructive')}>
                Hourly Rate (€)
              </Label>
              <Input
                id="hourlyRateCents"
                name="hourlyRateCents"
                type="number"
                step="0.01"
                min="0"
                value={formData.hourlyRateCents === 0 ? '' : (formData.hourlyRateCents / 100).toFixed(2)}
                onChange={(e) => {
                  const euros = parseFloat(e.target.value)
                  handleFieldChange('hourlyRateCents', isNaN(euros) ? '0' : String(Math.round(euros * 100)))
                }}
                placeholder="e.g. 45.00"
                className={cn(errors?.fields.hourlyRateCents && 'border-destructive focus-visible:ring-destructive')}
              />
              {formData.hourlyRateCents > 0 && !errors?.fields.hourlyRateCents && (
                <p className="text-xs text-muted-foreground">
                  Stored as {(formData.hourlyRateCents / 100).toFixed(2)} € / hour ({formData.hourlyRateCents} cents/hour)
                </p>
              )}
              {errors?.fields.hourlyRateCents && (
                <p className="text-xs text-destructive">{errors.fields.hourlyRateCents}</p>
              )}
            </div>

            {/* Footer actions */}
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" type="button" onClick={handleClose} disabled={isSubmitting}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting
                  ? (isEditMode ? 'Updating...' : 'Creating...')
                  : (isEditMode ? 'Save changes' : 'Create staff member')}
              </Button>
            </div>
          </form>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

/**
 * StaffListPage — Management list page for staff members.
 *
 * Displays a searchable, paginated DataTable with columns for:
 * - Name (clickable to edit)
 * - Role badge (Mechanic/Manager)
 * - Hourly rate (displayed as currency €X.XX/h)
 * - Active status toggle switch (click to toggle without opening dialog)
 *
 * Inactive staff members are visually distinguished with muted styling.
 */

import { useState, useCallback } from 'react'
import toast from 'react-hot-toast'
import { useStaffMembers } from '../hooks/useStaffMembers.js'
import type { StaffMemberDetail } from '../types.js'
import { formatHourlyRate } from '../types.js'
import { updateStaffMember } from '../api.js'
import {
  DataTable,
  type DataTableColumn,
} from '@/components/ui/DataTable.js'
import { Button } from '@/components/ui/button.js'
import { Switch } from '@/components/ui/switch.js'
import { StaffFormDialog } from './StaffFormDialog.js'

// ---------------------------------------------------------------------------
// Column Cell Components
// ---------------------------------------------------------------------------

function RoleBadge({ role }: { role: 'mechanic' | 'manager' }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        role === 'mechanic'
          ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300'
          : 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
      }`}
    >
      {role === 'mechanic' ? 'Mechanic' : 'Manager'}
    </span>
  )
}

function ActiveToggle({
  isActive,
  onToggle,
}: {
  isActive: boolean
  onToggle: () => void
}) {
  return (
    <div className="flex items-center gap-2">
      <Switch
        checked={isActive}
        onCheckedChange={() => onToggle()}
        aria-label={`Toggle active status — currently ${isActive ? 'active' : 'inactive'}`}
      />
      <span
        className={`text-xs font-medium ${
          isActive
            ? 'text-emerald-600 dark:text-emerald-400'
            : 'text-gray-400 dark:text-gray-500'
        }`}
      >
        {isActive ? 'Active' : 'Inactive'}
      </span>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Page Component
// ---------------------------------------------------------------------------

export function StaffListPage() {
  const [dialogOpen, setDialogOpen] = useState(false)
  // Track which staff member is being edited (null = create mode)
  const [editingStaff, setEditingStaff] = useState<{
    id: string
    name: string
    role: 'mechanic' | 'manager'
    hourlyRateCents: number
  } | null>(null)

  const {
    staffMembers,
    totalItems,
    currentPage,
    pageSize,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  } = useStaffMembers()

  // -----------------------------------------------------------------------
  // Handlers
  // ---------------------------------------------------------------------------

  const handleRowClick = useCallback((staff: StaffMemberDetail) => {
    setEditingStaff({
      id: staff.id,
      name: staff.name,
      role: staff.role as 'mechanic' | 'manager',
      hourlyRateCents: staff.hourlyRate,
    })
